from decimal import Decimal, InvalidOperation

_CENT = Decimal("0.01")


def allocate_by_ratios(total: str, ratios: list) -> list[Decimal]:
    if not isinstance(total, str):
        raise ValueError("total must be a string")
    try:
        amount = Decimal(total)
    except (InvalidOperation, ValueError):
        raise ValueError(f"invalid total: {total!r}") from None
    if not amount.is_finite():
        raise ValueError("total must be finite")
    # Rule 1: at most 2 decimal places. Use exponent check to avoid
    # InvalidOperation from quantize on very large values.
    try:
        exp = amount.as_tuple().exponent
    except Exception:
        raise ValueError("total must be finite") from None
    if exp < -2:
        raise ValueError("total must have at most 2 decimal places")
    if not isinstance(ratios, list) or len(ratios) == 0:
        raise ValueError("ratios must be a non-empty list")
    weights = []
    for entry in ratios:
        if isinstance(entry, bool):
            raise ValueError("bool weights are not accepted")
        if isinstance(entry, int):
            weight = Decimal(entry)
        elif isinstance(entry, Decimal):
            weight = entry
        elif isinstance(entry, str):
            try:
                weight = Decimal(entry)
            except (InvalidOperation, ValueError):
                raise ValueError(f"invalid weight: {entry!r}") from None
        else:
            raise ValueError(f"invalid weight: {entry!r}")
        if not weight.is_finite():
            raise ValueError("weights must be finite")
        if weight < 0:
            raise ValueError("weights must be >= 0")
        weights.append(weight)
    total_weight = sum(weights, Decimal("0"))
    if total_weight <= 0:
        raise ValueError("at least one weight must be > 0")
    negative = amount < 0
    abs_amount = abs(amount)
    # Rule 1/5: compute cents exactly without context precision loss.
    # amount has at most 2 decimal places, so exponent >= -2.
    # cents = int_digits * 10**(exponent+2)
    t = abs_amount.as_tuple()
    e = t.exponent
    digits = t.digits
    int_digits = 0
    for d in digits:
        int_digits = int_digits * 10 + d
    # e+2 >= 0 by validation
    cents = int_digits * (10 ** (e + 2)) if (e + 2) != 0 else int_digits
    # Rule 5-6: exact arithmetic for shares / remainders.
    # Convert all weights to integers at a common scale 10**max_scale.
    exponents = [w.as_tuple().exponent for w in weights]
    max_scale = 0
    for ex in exponents:
        if ex < 0 and -ex > max_scale:
            max_scale = -ex
    weight_ints = []
    for w, ex in zip(weights, exponents):
        tup = w.as_tuple()
        digs = tup.digits
        # build int value of digits
        int_d = 0
        for d in digs:
            int_d = int_d * 10 + d
        # apply sign (weights are >=0 so sign is 0, but handle -0)
        # value = int_d * 10**ex (sign already validated)
        # scaled = value * 10**max_scale = int_d * 10**(ex+max_scale)
        exp2 = ex + max_scale
        if exp2 == 0:
            wi = int_d
        elif exp2 > 0:
            wi = int_d * (10 ** exp2)
        else:
            # Should not happen because max_scale >= -ex, but keep safe
            wi = int_d // (10 ** (-exp2))
        # handle negative zero sign if any (should be 0)
        if tup.sign == 1:
            wi = -wi
        weight_ints.append(wi)
    total_weight_scaled = sum(weight_ints)
    # total_weight_scaled > 0 because at least one weight >0
    floors = []
    remainder_nums = []
    for wi in weight_ints:
        numer = cents * wi
        floor_cents = numer // total_weight_scaled
        rem = numer % total_weight_scaled
        floors.append(floor_cents)
        remainder_nums.append(rem)
    remaining = cents - sum(floors)
    # Only positive-weight entries may receive remainder cents.
    # Sort by remainder desc, weight desc, index asc.
    order = sorted(
        (i for i, w in enumerate(weights) if w > 0),
        key=lambda i: (-remainder_nums[i], -weight_ints[i], i)
    )
    for i in order[:remaining]:
        floors[i] += 1
    parts = []
    for floor_cents in floors:
        part = (Decimal(floor_cents) / Decimal(100)).quantize(_CENT)
        if negative and part != 0:
            part = -part
        parts.append(part)
    return parts
